import{_ as a,o as i,c as o,b as l}from"./chunks/framework.BAcwvmoc.js";const m=JSON.parse('{"title":"Proyecto docente: Construye tu propio asistente de IA con PHP y Docker","description":"","frontmatter":{},"headers":[],"relativePath":"04_php/100_proyecto_ia/index.md","filePath":"04_php/100_proyecto_ia/index.md"}'),r={name:"04_php/100_proyecto_ia/index.md"};function n(s,e,t,c,d,p){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="proyecto-docente-construye-tu-propio-asistente-de-ia-con-php-y-docker" tabindex="-1">Proyecto docente: Construye tu propio asistente de IA con PHP y Docker <a class="header-anchor" href="#proyecto-docente-construye-tu-propio-asistente-de-ia-con-php-y-docker" aria-label="Permalink to &quot;Proyecto docente: Construye tu propio asistente de IA con PHP y Docker&quot;">​</a></h1><p>Actúa como un profesor experto en Desarrollo Web en Entorno Servidor (DWES), desarrollador senior de PHP y especialista en diseño de prácticas educativas de Formación Profesional.</p><p>Quiero que me ayudes a <strong>diseñar, desarrollar, documentar y validar una práctica completa y motivadora</strong> para mis alumnos de DWES.</p><p>No quiero que generes todo el proyecto de golpe. Trabajaremos de manera incremental, tomando decisiones y validando cada fase antes de continuar.</p><h2 id="_1-contexto-docente" tabindex="-1">1. Contexto docente <a class="header-anchor" href="#_1-contexto-docente" aria-label="Permalink to &quot;1. Contexto docente&quot;">​</a></h2><p>Los alumnos están aprendiendo desarrollo web en entorno servidor con PHP.</p><p>Conocen o habrán trabajado:</p><ul><li>Variables, operadores y estructuras de control.</li><li>Funciones.</li><li>Arrays indexados, asociativos y multidimensionales.</li><li>Formularios HTML y métodos GET y POST.</li><li>Separación entre lógica de procesamiento y presentación.</li><li>Programación orientada a objetos.</li><li>Sesiones PHP.</li><li>Fundamentos de HTTP.</li><li>Docker y Docker Compose.</li></ul><p>La práctica debe servir para introducir y consolidar:</p><ul><li>Servicios web y APIs REST.</li><li>Consumo de APIs mediante PHP y cURL.</li><li>Intercambio de información mediante JSON.</li><li>Gestión de errores HTTP.</li><li>Integración de servicios externos.</li><li>Desarrollo de una aplicación web estructurada.</li></ul><p>No utilizaremos Laravel ni otros frameworks PHP.</p><h2 id="_2-objetivo-del-proyecto" tabindex="-1">2. Objetivo del proyecto <a class="header-anchor" href="#_2-objetivo-del-proyecto" aria-label="Permalink to &quot;2. Objetivo del proyecto&quot;">​</a></h2><p>Los alumnos construirán una aplicación web denominada provisionalmente <strong>Mi Asistente IA</strong>, que permitirá conversar con un modelo de inteligencia artificial ejecutado mediante Ollama.</p><p>La aplicación tendrá una interfaz moderna, atractiva y responsive, similar a la de un asistente conversacional.</p><p>Debe ser un proyecto que motive a los alumnos porque podrán utilizar su propia aplicación para consultar dudas de programación, generar ejemplos y recibir explicaciones.</p><p>La IA se ejecutará en un servicio independiente y la aplicación PHP consumirá su API HTTP.</p><h2 id="_3-tecnologias" tabindex="-1">3. Tecnologías <a class="header-anchor" href="#_3-tecnologias" aria-label="Permalink to &quot;3. Tecnologías&quot;">​</a></h2><p>Utilizaremos:</p><ul><li>PHP 8.4 o superior.</li><li>HTML5.</li><li>CSS.</li><li>Tailwind CSS 4.</li><li>DaisyUI 5.</li><li>JavaScript únicamente cuando sea necesario.</li><li>Docker y Docker Compose.</li><li>Ollama como servidor de IA.</li><li>Un modelo pequeño adecuado para equipos docentes.</li><li>cURL para las peticiones HTTP.</li><li>JSON para intercambiar información.</li><li>Sesiones PHP para conservar conversaciones.</li></ul><p>Prefiero utilizar componentes de DaisyUI y minimizar las clases de Tailwind.</p><p>No quiero HTML con decenas de clases utilitarias que dificulten su comprensión.</p><p>La interfaz debe ser elegante, clara, moderna y atractiva, pero su implementación debe seguir siendo comprensible para alumnos de FP.</p><p>Podemos utilizar una hoja CSS propia para los estilos específicos.</p><p>Justifica cualquier biblioteca o dependencia adicional antes de incorporarla.</p><h2 id="_4-entregable-a-enunciado-completo-para-los-alumnos" tabindex="-1">4. Entregable A: enunciado completo para los alumnos <a class="header-anchor" href="#_4-entregable-a-enunciado-completo-para-los-alumnos" aria-label="Permalink to &quot;4. Entregable A: enunciado completo para los alumnos&quot;">​</a></h2><p>Necesito un enunciado detallado, redactado en español y preparado para incorporarlo a mis apuntes de VitePress.</p><p>Debe contener:</p><h3 id="_4-1-presentacion" tabindex="-1">4.1. Presentación <a class="header-anchor" href="#_4-1-presentacion" aria-label="Permalink to &quot;4.1. Presentación&quot;">​</a></h3><ul><li>Título atractivo.</li><li>Descripción del proyecto.</li><li>Motivación y utilidad real.</li><li>Objetivos de aprendizaje.</li><li>Tecnologías utilizadas.</li><li>Conocimientos previos.</li><li>Duración estimada.</li><li>Resultado final esperado.</li></ul><p>Utiliza un lenguaje motivador, pero riguroso.</p><h3 id="_4-2-explicacion-de-la-arquitectura" tabindex="-1">4.2. Explicación de la arquitectura <a class="header-anchor" href="#_4-2-explicacion-de-la-arquitectura" aria-label="Permalink to &quot;4.2. Explicación de la arquitectura&quot;">​</a></h3><p>Explica cómo se relacionan:</p><ol><li>Navegador del alumno.</li><li>Aplicación PHP.</li><li>API HTTP de Ollama.</li><li>Modelo de lenguaje.</li><li>Sesiones PHP.</li></ol><p>Incluye diagramas de arquitectura y secuencia, preferentemente Mermaid, y propón imágenes didácticas cuando aporten valor.</p><p>Explica claramente que PHP consume una API, pero no ejecuta directamente el modelo de IA.</p><h3 id="_4-3-requisitos-funcionales" tabindex="-1">4.3. Requisitos funcionales <a class="header-anchor" href="#_4-3-requisitos-funcionales" aria-label="Permalink to &quot;4.3. Requisitos funcionales&quot;">​</a></h3><p>Desarrolla detalladamente los siguientes requisitos.</p><p><strong>RF1. Cliente básico de IA — Obligatorio</strong></p><ul><li>Mostrar un formulario para introducir preguntas.</li><li>Validar la entrada.</li><li>Enviar la pregunta mediante POST a PHP.</li><li>Construir una petición HTTP hacia Ollama.</li><li>Codificar los datos en JSON.</li><li>Procesar la respuesta JSON.</li><li>Mostrar la respuesta del modelo.</li><li>Gestionar errores de conexión y respuestas incorrectas.</li><li>Separar la lógica PHP de la presentación HTML.</li></ul><p><strong>RF2. Configuración del asistente — Obligatorio</strong></p><ul><li>Seleccionar entre los modelos permitidos y disponibles.</li><li>Configurar parámetros sencillos, como la longitud máxima de respuesta.</li><li>Definir instrucciones de comportamiento para el asistente.</li><li>Ofrecer varios perfiles, por ejemplo: <ul><li>Tutor de PHP.</li><li>Experto en Docker.</li><li>Profesor de bases de datos.</li><li>Asistente general.</li></ul></li><li>Mostrar el modelo utilizado.</li><li>Validar las opciones enviadas desde el formulario.</li></ul><p><strong>RF3. Historial de conversaciones — Ampliación</strong></p><ul><li>Conservar preguntas y respuestas utilizando sesiones PHP.</li><li>Mostrar el historial en formato conversacional.</li><li>Permitir iniciar una nueva conversación.</li><li>Mantener el contexto entre preguntas cuando corresponda.</li><li>Diferenciar entre almacenar el historial visual y enviar el contexto al modelo.</li><li>Establecer límites para evitar conversaciones excesivamente grandes.</li></ul><p>Propón requisitos funcionales adicionales si mejoran el proyecto, pero distingue claramente entre obligatorios y ampliaciones.</p><p>Para cada requisito incluye:</p><ul><li>Descripción.</li><li>Comportamiento esperado.</li><li>Datos de entrada.</li><li>Resultado esperado.</li><li>Conceptos PHP necesarios.</li><li>Criterios de aceptación.</li><li>Posibles errores.</li><li>Pruebas para verificar su funcionamiento.</li></ul><h3 id="_4-4-fases-de-desarrollo" tabindex="-1">4.4. Fases de desarrollo <a class="header-anchor" href="#_4-4-fases-de-desarrollo" aria-label="Permalink to &quot;4.4. Fases de desarrollo&quot;">​</a></h3><p>Organiza la práctica en fases progresivas, de forma que el alumno obtenga resultados funcionales desde el principio.</p><p>Cada fase debe indicar:</p><ul><li>Objetivo.</li><li>Trabajo que debe realizar.</li><li>Conocimientos necesarios.</li><li>Archivos implicados.</li><li>Resultado verificable.</li><li>Tiempo estimado.</li></ul><p>No proporciones la solución completa dentro del enunciado.</p><h3 id="_4-5-material-visual" tabindex="-1">4.5. Material visual <a class="header-anchor" href="#_4-5-material-visual" aria-label="Permalink to &quot;4.5. Material visual&quot;">​</a></h3><p>Quiero que el enunciado incluya imágenes cuando resulten útiles:</p><ul><li>Arquitectura de la aplicación.</li><li>Comunicación HTTP.</li><li>Ejemplo visual del chat.</li><li>Configuración del asistente.</li><li>Historial de conversación.</li></ul><p>Distingue entre diagramas técnicos y mockups de interfaz.</p><p>Las imágenes deben ayudar a comprender el proyecto y despertar interés, no ser meramente decorativas.</p><p>Genera imágenes independientes cuando sea necesario.</p><h3 id="_4-6-evaluacion" tabindex="-1">4.6. Evaluación <a class="header-anchor" href="#_4-6-evaluacion" aria-label="Permalink to &quot;4.6. Evaluación&quot;">​</a></h3><p>Prepara una rúbrica de evaluación con criterios objetivos.</p><p>Valora especialmente:</p><ul><li>Funcionamiento.</li><li>Uso correcto de PHP.</li><li>Consumo de la API.</li><li>Procesamiento de JSON.</li><li>Organización del código.</li><li>Gestión de errores.</li><li>Calidad de la interfaz.</li><li>Comprensión de la solución.</li></ul><p>Distingue claramente los requisitos obligatorios de las ampliaciones.</p><h2 id="_5-entregable-b-plantillas-de-interfaz" tabindex="-1">5. Entregable B: plantillas de interfaz <a class="header-anchor" href="#_5-entregable-b-plantillas-de-interfaz" aria-label="Permalink to &quot;5. Entregable B: plantillas de interfaz&quot;">​</a></h2><p>Necesito plantillas HTML con Tailwind CSS y DaisyUI.</p><p>La interfaz debe incluir:</p><ul><li>Cabecera con nombre e identidad visual del asistente.</li><li>Área principal de conversación.</li><li>Mensajes diferenciados del usuario y de la IA.</li><li>Formulario para introducir preguntas.</li><li>Botón de envío.</li><li>Indicador de procesamiento.</li><li>Panel de configuración.</li><li>Selector de perfil del asistente.</li><li>Selector de modelo.</li><li>Historial de conversación.</li><li>Botón para iniciar una conversación nueva.</li><li>Mensajes de error claros.</li></ul><p>Debe funcionar correctamente en escritorio y móvil.</p><p>Quiero una estética moderna y cuidada, sin complejidad innecesaria.</p><p>Prioriza los componentes <code>card</code>, <code>chat</code>, <code>textarea</code>, <code>select</code>, <code>button</code>, <code>alert</code>, <code>loading</code> y otros componentes oficiales de DaisyUI.</p><p>Utiliza una hoja CSS propia cuando simplifique el código.</p><p>No mezcles la lógica de negocio con la presentación.</p><h2 id="_6-entregable-c-solucion-completa-para-el-profesor" tabindex="-1">6. Entregable C: solución completa para el profesor <a class="header-anchor" href="#_6-entregable-c-solucion-completa-para-el-profesor" aria-label="Permalink to &quot;6. Entregable C: solución completa para el profesor&quot;">​</a></h2><p>Implementa una solución funcional en PHP puro.</p><p>Propón una estructura de carpetas clara y proporcionada a la dificultad de la práctica.</p><p>Separa, cuando proceda:</p><ul><li>Controladores.</li><li>Vistas.</li><li>Servicios.</li><li>Configuración.</li><li>Funciones auxiliares.</li><li>Recursos CSS y JavaScript.</li></ul><p>Podemos utilizar clases para encapsular la comunicación con Ollama y funciones para operaciones sencillas.</p><p>No introduzcas una arquitectura MVC compleja ni patrones de diseño innecesarios.</p><p>La solución debe incluir:</p><ul><li>Todos los archivos completos.</li><li>Explicación de las responsabilidades de cada archivo.</li><li>Código comentado cuando aporte valor didáctico.</li><li>Validaciones.</li><li>Gestión de excepciones y errores.</li><li>Uso correcto de sesiones.</li><li>Configuración de la URL del servidor Ollama.</li><li>Control de los modelos permitidos.</li><li>Tiempos máximos de espera.</li><li>Escape de la salida HTML para evitar XSS.</li><li>Protección básica de los formularios y las peticiones.</li><li>Tratamiento seguro de la respuesta del modelo.</li></ul><p>Utiliza cURL de forma explícita para que los alumnos comprendan cómo se construye una petición HTTP.</p><p>Evita dependencias innecesarias.</p><h2 id="_7-entregable-d-infraestructura-docker" tabindex="-1">7. Entregable D: infraestructura Docker <a class="header-anchor" href="#_7-entregable-d-infraestructura-docker" aria-label="Permalink to &quot;7. Entregable D: infraestructura Docker&quot;">​</a></h2><p>Prepara una infraestructura reproducible mediante Docker Compose.</p><p>Debe incluir:</p><ul><li>Servicio PHP con Apache.</li><li>Extensión cURL.</li><li>Servicio Ollama.</li><li>Volúmenes necesarios.</li><li>Red interna para comunicar los servicios.</li><li>Configuración mediante variables de entorno cuando corresponda.</li><li>Procedimiento para descargar el modelo.</li><li>Comandos de arranque y parada.</li><li>Comprobaciones de funcionamiento.</li><li>Diagnóstico de problemas habituales.</li></ul><p>La API de Ollama no debe exponerse públicamente sin controles de acceso.</p><p>Valora la posibilidad de utilizar un servidor Ollama común para toda la clase.</p><p>Explica las diferencias entre desplegar Ollama localmente y consumir una instancia compartida.</p><h2 id="_8-entregable-e-documentacion-para-vitepress" tabindex="-1">8. Entregable E: documentación para VitePress <a class="header-anchor" href="#_8-entregable-e-documentacion-para-vitepress" aria-label="Permalink to &quot;8. Entregable E: documentación para VitePress&quot;">​</a></h2><p>El material docente se incorporará a mi web de apuntes VitePress.</p><p>Necesito Markdown crudo, preparado para copiar a los archivos <code>.md</code>.</p><p>Podemos utilizar:</p><ul><li>Bloques de código con resaltado de sintaxis.</li><li>Tablas.</li><li>Mermaid.</li><li>Contenedores personalizados.</li><li>Componentes Vue existentes.</li></ul><p>No inventes componentes VitePress que no hayamos definido previamente.</p><p>Separa el material del alumno de la solución del profesor.</p><h2 id="_9-metodologia-de-trabajo" tabindex="-1">9. Metodología de trabajo <a class="header-anchor" href="#_9-metodologia-de-trabajo" aria-label="Permalink to &quot;9. Metodología de trabajo&quot;">​</a></h2><p>Quiero desarrollar el proyecto contigo paso a paso.</p><p>Seguiremos este orden:</p><ol><li>Definir el alcance definitivo y la duración.</li><li>Diseñar la experiencia de usuario.</li><li>Crear mockups visuales.</li><li>Diseñar y validar la infraestructura Docker.</li><li>Probar la API de Ollama.</li><li>Implementar un cliente PHP mínimo.</li><li>Diseñar la estructura definitiva del proyecto.</li><li>Implementar los requisitos funcionales.</li><li>Preparar el enunciado detallado.</li><li>Preparar la solución del profesor.</li><li>Crear pruebas y rúbrica.</li><li>Preparar el material final para VitePress.</li></ol><p>Antes de cada fase, explícame brevemente qué vamos a hacer y por qué.</p><p>No avances a la siguiente fase sin mi confirmación.</p><p>Si detectas una alternativa técnica o pedagógica mejor, propónla y justifícala.</p><p><strong>Empieza por la fase 1: analiza el alcance de la práctica, los requisitos, su dificultad y el tiempo necesario. Propón una planificación realista y espera mi aprobación antes de generar código.</strong></p><div class="daws-referencias daws-container"><p class="daws-referencias__kicker"><i class="fa-solid fa-link" aria-hidden="true"></i> Referencias </p><p class="daws-referencias__sub">Dónde buscar información</p><div class="daws-referencias__body"><p><a href="https://www.youtube.com/watch?v=aRuKmxMiRqo" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=aRuKmxMiRqo</a></p></div></div>',105)])])}const b=a(r,[["render",n]]);export{m as __pageData,b as default};
